{%- set creditor = doc.client_name or doc.client or "" -%}
{%- set cur = doc.debt_currency or "BHD" -%}
{%- set amount = "{:,.3f}".format(doc.debt_balance_amount or 0) -%}
{%- set today = frappe.utils.formatdate(frappe.utils.nowdate(), "d MMMM yyyy") -%}
{%- set debtor = (doc.debtor_name or "") -%}
<style>
@page { size: A4; margin: 0; }
.print-format { margin-top: 0mm; margin-bottom: 0mm; margin-left: 0mm; margin-right: 0mm; padding: 0; }
.pg { position: relative; width: 594.96pt; height: 835pt; margin: 0 auto; overflow: hidden; background: #fff; color: #000;
  font-family: Arial, Helvetica, "Liberation Sans", sans-serif; font-size: 9pt; line-height: 10.35pt; }
.pg .a { position: absolute; margin: 0; padding: 0; white-space: nowrap; }
.pg .en { left: 43.9pt; direction: ltr; text-align: left; }
.pg .ar { right: 50.2pt; width: 246.5pt; font-size: 9.34pt; direction: rtl; text-align: right; white-space: normal; }
.pg .ltr-r { right: 49.1pt; font-size: 9pt; direction: ltr; text-align: right; }
.pg .th { font-family: Tahoma, Verdana, Arial, sans-serif; font-weight: bold; letter-spacing: -0.033em; color: #101010; text-align: center; left: 0; width: 594.96pt; }
.pg .flow p { margin: 0 0 6.15pt 0; padding: 0; white-space: nowrap; }
.pg .enf { left: 43.9pt; width: 250pt; direction: ltr; text-align: left; white-space: normal; }
.pg .enf p.wr { white-space: normal; }
.pg .arf { right: 50.2pt; width: 246.5pt; direction: rtl; text-align: right; font-size: 9.34pt; }
.pg .arf p { white-space: normal; }
.pg b { font-weight: bold; }
.pg .u { text-decoration: underline; font-weight: bold; }
.pg .nm { text-decoration: underline; text-transform: uppercase; }
.pg img { position: absolute; }
.pg .ln { position: absolute; left: 42.75pt; width: 509.25pt; top: 678pt; height: 0.75pt; background: #dcdcdc; }
.pg .ft { position: absolute; top: 683.7pt; left: 0; width: 574.96pt; text-align: center; font-size: 7.4pt; color: #666; line-height: 9pt; }
</style>
<div class="pg">
<img src="/assets/debt_recovery/images/primegulf_logo.jpg" style="left:78pt;top:50.2pt;width:84.7pt;height:56.3pt">
<img src="/assets/debt_recovery/images/primegulf_header_text.png" style="left:226pt;top:53pt;width:298pt;height:57pt">
<div class="a" style="left:48.7pt;top:123.3pt;font-family:Tahoma,Verdana,Arial,sans-serif;font-weight:bold;letter-spacing:-0.033em;font-size:9.6pt;line-height:11.5pt;color:#101010">{{ today }}</div>
<div class="a th" style="top:152.9pt;font-size:11pt;line-height:13.2pt;letter-spacing:-0.018em;">URGENT – LEGAL ACTION REQUEST RECEIVED</div>
<div class="a th" style="top:173.0pt;font-size:12pt;line-height:14.4pt;letter-spacing:-0.006em;"><span class="nm">{{ debtor }}</span></div>
<div class="a flow enf" style="top:215.0pt"><p class=""><b>Dear {{ debtor }},</b></p><p class="">Greetings from <b>Prime Gulf Global Recoveries W.L.L.</b></p><p class="wr">We are writing on behalf of <b>{{ creditor }}</b> regarding the outstanding balance of <b>{{ cur }} {{ amount }}</b> under your account.</p><p class="">Please be informed that <b>we have received a request from<br>our client regarding the commencement of legal action in<br>connection with the outstanding balance</b>.</p><p class="">Before the matter proceeds further, we are inviting you to visit<br>our office <b>within two (2) days from receipt of this letter</b> to<br>discuss the outstanding balance and explore an appropriate<br>settlement or payment arrangement.</p><p class="">Kindly <b>confirm your availability with us immediately</b>, and<br>we will arrange a suitable appointment for you at our office.</p><p class="">Your prompt cooperation is strongly encouraged so that the<br>matter can be discussed and resolved <b>before any legal filing<br>is initiated, where possible, without further notice</b>.</p><p class="">For confirmation and appointment scheduling, please contact<br>us at <b>+973 3304 6888</b>, between <b>8:00 AM</b> and <b>5:00 PM</b>.</p><p class="">We look forward to your immediate response and<br>cooperation.</p><p class=""><b>Yours faithfully,<br>Prime Gulf Global Recoveries W.L.L.</b></p></div><div class="a flow arf" style="top:215.0pt"><p style=""><b>السيد/السيدة: {{ debtor }}،</b></p><p style=""><b>تحية طيبة من شركة برايم جلف العالمية لتحصيل الديون ذ.م.م.</b></p><p style=""><b>نتواصل معكم نيابةً عن {{ creditor }} بخصوص المبلغ المستحق البالغ {{ amount }} دينار بحريني على حسابكم.</b></p><div style="height:16.5pt"></div><p style="text-align:left">يرجى العلم بأننا <b>قد تلقينا طلباً من موكلنا بشأن البدء في اتخاذ إجراءات قانونية<br>فيما يتعلق بالمبلغ المستحق</b>.</p><div style="height:16.5pt"></div><p style="">وقبل أن يتم اتخاذ أي إجراءات أخرى، ندعوكم إلى زيارة مكتبنا <b>خلال يومين (2) من تاريخ استلامكم لهذا الخطاب</b>، وذلك لمناقشة المبلغ المستحق وبحث إمكانية الوصول إلى تسوية مناسبة أو ترتيب خطة للسداد.</p><p style="">يرجى <b>تأكيد موعد زيارتكم معنا في أقرب وقت ممكن</b>، وسنقوم بتحديد موعد مناسب لكم في مكتبنا.</p><p style="">نحثكم على التعاون واتخاذ الإجراءات اللازمة بشكل عاجل، حتى يتسنى مناقشة الموضوع والعمل على تسويته <b>قبل البدء في أي إجراءات قانونية، وحيثما أمكن، دون الحاجة إلى إرسال إشعار آخر</b>.</p><p style="">لتأكيد الموعد وتحديد موعد الزيارة، يرجى التواصل معنا على الرقم <b><bdi dir="ltr">+973 3304 6888</bdi></b>، من الساعة <b>8:00 صباحاً حتى 5:00 مساءً</b>.</p><div style="height:16.5pt"></div><p style="">وتفضلوا بقبول فائق الاحترام والتقدير،</p><p style="direction:ltr;text-align:right"><b>Prime Gulf Global Recoveries W.L.L.</b></p></div>
<img src="/assets/debt_recovery/images/primegulf_signature.png" style="left:247.1pt;top:492.2pt;width:60pt;height:45pt"><img src="/assets/debt_recovery/images/primegulf_stamp.png" style="left:310.1pt;top:492.2pt;width:86.2pt;height:84.8pt">
